package com.eatwhat.service;

import org.junit.jupiter.api.Test;
import com.eatwhat.dto.*;
import com.eatwhat.dto.AssistantShoppingContract.*;
import com.eatwhat.dto.AssistantV4Contract.*;
import com.eatwhat.entity.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class AssistantShoppingPreviewTest {
 @Test void list_race_at_batch_lock_requires_repreview_without_retrying_stale_binding() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask task=f.preview();doThrow(new ShoppingListService.VersionConflictException(1L)).when(f.lists).batchAdd(eq(1L),any());ControlledToolTask done=f.confirm(task);assertEquals("WORKFLOW_VERSION_CONFLICT",done.errorCode);assertFalse(done.retryable);assertTrue(f.items.isEmpty());}
 @Test void shopping_receipt_and_preview_point_to_the_purchase_list(){try{AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask task=f.preview();assertEquals("shopping_preview",f.adapter.previewCard(task).getData().get("action"));ControlledToolTask done=f.confirm(task);Map<?,?> card=(Map<?,?>)done.steps.get(0).result.get("card");assertEquals("shopping_preview",((Map<?,?>)card.get("data")).get("action"));assertEquals("已加入采购清单",card.get("text"));}catch(Exception e){throw new AssertionError(e);}}
 @Test void text_only_manual_quantity_remains_visible_without_fabricated_number() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();f.confirm(f.preview());ShoppingItem user=f.items.get(0);user.setUserOverride(true);user.setQuantityValue(null);user.setQuantityText("半袋");ControlledToolTask task=f.preview();Map<String,Object> row=f.rows(task).stream().filter(r->user.getDisplayName().equals(r.get("name"))).findFirst().get();assertNull(row.get("quantity"));assertEquals("半袋",row.get("quantityText"));assertEquals("completed",f.confirm(task).status);assertEquals("半袋",f.items.stream().filter(i->i.getId().equals(user.getId())).findFirst().get().getQuantityText());}
 @Test void restarted_services_preserve_new_token_and_old_task_invalidation() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask old=f.workflow(false);ControlledToolTask fresh=f.adapter.repreview(1L,old.id,f.choose(old));f.f.persistence.store=f.f.persistence.newStore();f.f.initialize(f.f.persistence.now);f.initialize();assertEquals(fresh.id,f.f.persistence.store.findTurn(1L,f.f.turnId).getPendingAction().getTaskId());assertEquals("PREVIEW_REPLACED",f.confirm(old).errorCode);assertEquals("completed",f.confirm(fresh).status);assertEquals(1,f.items.size());verifyNoInteractions(f.model);}
 @Test void new_conversation_plan_preview_repairs_failed_alias_before_allocating_scope() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask draft=f.preview();f.confirm(draft);ControlledToolTask calendar=f.calendar("2026-12-31","dinner");doThrow(new IllegalStateException("offline aliases")).when(f.aliases).insert(anyLong(),anyString(),anyString());assertTrue(f.confirm(calendar).retryable);when(f.aliases.savedCalendarTask(1L,"2026-12-31","dinner",1L)).thenReturn(calendar.id);assertThrows(IllegalStateException.class,()->f.adapter.prepareShopping(1L,f.plan("2026-12-31","dinner"),"retry-plan"));f.workingAliases();ControlledToolTask plan=f.adapter.prepareShopping(1L,f.plan("2026-12-31","dinner"),"retry-plan");assertEquals(draft.steps.get(0).binding.get("purchaseScopeId"),plan.steps.get(0).binding.get("purchaseScopeId"));assertEquals("completed",f.confirm(plan).status);assertEquals(2,f.items.size());}
 @Test void locking_current_recipe_and_quality_read_prevents_snapshot_race() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.preview();Dish changed=f.f.domain.json.convertValue(f.f.domain.reviewed.get(0),Dish.class);changed.setIngredientsAmounts("花生|1|g");when(f.aliases.lockDishes(eq(1L),anyList())).thenReturn(Collections.singletonList(changed));assertEquals("WORKFLOW_VERSION_CONFLICT",f.confirm(t).errorCode);assertTrue(f.items.isEmpty());}
 @Test void shopping_preview_requires_real_registered_adapter() throws Exception {
  assertTrue(ControlledToolHarnessService.Extension.class.isAssignableFrom(Class.forName("com.eatwhat.service.ShoppingAssistantToolAdapter")));
 }
 @Test void unknown_servings_do_not_default_to_two() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();f.f.domain.reviewed.get(0).setFl(null);f.refreshDraft();ControlledToolTask t=f.preview();assertNull(f.rows(t).get(0).get("quantity"));assertEquals("按需",f.rows(t).get(0).get("quantityText"));assertEquals("completed",f.confirm(t).status);assertNull(f.items.get(0).getQuantityValue());}
 @Test void no_price_stays_empty() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();for(Map<String,Object> row:f.rows(f.preview()))assertNull(row.get("price"));}
 @Test void draft_shopping_does_not_create_calendar() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();assertEquals("completed",f.confirm(f.preview()).status);assertEquals(2,f.items.size());assertTrue(f.f.domain.slots.isEmpty());verify(f.f.domain.plans,never()).insert(any());}
 @Test void recipe_changed_after_preview() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.preview();f.f.domain.reviewed.get(0).setIngredientsAmounts("花生|100|g");assertEquals("WORKFLOW_VERSION_CONFLICT",f.confirm(t).errorCode);assertTrue(f.items.isEmpty());}
 @Test void draft_change_invalidates_shopping_preview() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.preview();MealWorkspace w=f.f.domain.service.get(1L,"source");w.setRevision(5L);f.f.domain.sourceJson=f.f.domain.json.writeValueAsString(w);assertEquals("WORKFLOW_VERSION_CONFLICT",f.confirm(t).errorCode);assertTrue(f.items.isEmpty());}
 @Test void list_changed_before_confirm() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.preview();f.list.setVersion(1L);assertEquals("WORKFLOW_VERSION_CONFLICT",f.confirm(t).errorCode);verify(f.lists,never()).batchAdd(anyLong(),any());}
 @Test void same_key_different_body_conflict() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ShoppingIntent intent=f.draft();f.adapter.prepareShopping(1L,intent,"fixed-key");intent.setExcludedOwnedIngredients(Collections.singletonList("盐"));assertThrows(MealConsumptionService.VersionConflict.class,()->f.adapter.prepareShopping(1L,intent,"fixed-key"));}
 @Test void selection_changed_invalidates_token() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.workflow(false);ControlledToolTask fresh=f.adapter.repreview(1L,t.id,f.choose(t));assertNotEquals(t.previewToken,fresh.previewToken);assertEquals(fresh.id,f.f.persistence.store.findTurn(1L,f.f.turnId).getPendingAction().getTaskId());assertEquals("PREVIEW_REPLACED",f.confirm(t).errorCode);assertTrue(f.items.isEmpty());assertEquals("completed",f.confirm(fresh).status);assertEquals(1,f.items.size());}
 @Test void lost_repreview_response_recovers_original_request_and_conflicting_body_is_rejected() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.workflow(false);RepreviewRequest r=f.choose(t);ControlledToolTask renewed=f.adapter.repreview(1L,t.id,r);assertEquals(renewed.id,f.adapter.repreview(1L,t.id,r).id);assertEquals(renewed.id,f.f.harness.byRequest(1L,r.getRequestId()).id);r.setSelectedSourceKeys(Collections.singletonList((String)f.rows(t).get(1).get("sourceKey")));assertThrows(MealConsumptionService.VersionConflict.class,()->f.adapter.repreview(1L,t.id,r));}
 @Test void expired_preview_can_be_repreviewed_but_cancelled_parent_cannot() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.workflow(false);f.f.persistence.store=new AssistantV4Store(f.f.persistence.db,f.f.persistence.locks,f.f.persistence.workspaces,f.f.domain.json,f.f.persistence.tx,Clock.fixed(Instant.ofEpochMilli(f.f.persistence.now+600001),ZoneOffset.UTC));f.f.initialize(f.f.persistence.now+600001);f.initialize();assertEquals("PREVIEW_EXPIRED",f.confirm(t).errorCode);ControlledToolTask renewed=f.adapter.repreview(1L,t.id,f.choose(t));assertNotEquals(t.id,renewed.id);assertEquals("completed",f.confirm(renewed).status);AssistantShoppingFixture cancelled=new AssistantShoppingFixture();ControlledToolTask old=cancelled.workflow(false);cancelled.f.persistence.store.cancelTurn(1L,cancelled.f.turnId);assertThrows(RuntimeException.class,()->cancelled.adapter.repreview(1L,old.id,cancelled.choose(old)));assertNotEquals("completed",cancelled.confirm(old).status);assertTrue(cancelled.items.isEmpty());}
 @Test void deleted_session_and_foreign_user_cannot_renew_or_confirm() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.workflow(false);assertThrows(RuntimeException.class,()->f.adapter.repreview(2L,t.id,f.choose(t)));f.f.persistence.store.deleteSession(1L,f.f.sessionId);assertThrows(RuntimeException.class,()->f.adapter.repreview(1L,t.id,f.choose(t)));assertNotEquals("completed",f.confirm(t).status);assertTrue(f.items.isEmpty());}
 @Test void draft_then_same_meal_plan_does_not_double_quantities() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask first=f.preview();assertEquals("completed",f.confirm(first).status);assertEquals("completed",f.confirm(f.calendar("2026-12-31","dinner")).status);ControlledToolTask plan=f.adapter.prepareShopping(1L,f.plan("2026-12-31","dinner"),"plan-buy");assertEquals(first.steps.get(0).binding.get("purchaseScopeId"),plan.steps.get(0).binding.get("purchaseScopeId"));ControlledToolTask done=f.confirm(plan);assertEquals("completed",done.status);assertEquals(0,done.steps.get(0).result.get("addedItemCount"));assertEquals(2,done.steps.get(0).result.get("mergedItemCount"));assertEquals(2,f.items.size());}
 @Test void same_dish_two_meals_keeps_two_sources() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();f.confirm(f.preview());f.confirm(f.calendar("2027-01-01","lunch"));ControlledToolTask other=f.adapter.prepareShopping(1L,f.plan("2027-01-01","lunch"),"other-meal");assertEquals("completed",f.confirm(other).status);assertEquals(2,f.groups.size());assertEquals(4,f.items.size());assertNotEquals(f.groups.get(0).getSelectionKey(),f.groups.get(1).getSelectionKey());}
 @Test void different_meals_keep_distinct_procurement() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();String a=f.scopes.resolveScope(1L,f.draft().getSourceRef());f.confirm(f.calendar("2027-01-01","lunch"));assertNotEquals(a,f.scopes.resolveScope(1L,f.plan("2027-01-01","lunch").getSourceRef()));}
 @Test void unchanged_plan_revision_increment_does_not_split_scope() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();f.confirm(f.calendar("2026-12-31","dinner"));String before=f.scopes.resolveScope(1L,f.plan("2026-12-31","dinner").getSourceRef());f.confirm(f.calendar("2026-12-31","dinner"));assertEquals(before,f.scopes.resolveScope(1L,f.plan("2026-12-31","dinner").getSourceRef()));}
 @Test void user_quantity_and_purchased_rows_preserved() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();f.confirm(f.preview());ShoppingItem user=f.items.get(0);user.setUserOverride(true);user.setQuantityValue(new BigDecimal("777"));user.setQuantityText("777g");user.setChecked(true);assertEquals("completed",f.confirm(f.preview()).status);ShoppingItem saved=f.items.stream().filter(i->i.getId().equals(user.getId())).findFirst().get();assertEquals(new BigDecimal("777"),saved.getQuantityValue());assertTrue(saved.getChecked());assertTrue(saved.getUserOverride());}
 @Test void owned_exclusions_bind_selection_and_cannot_remove_protected_items() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ShoppingIntent i=f.draft();i.setExcludedOwnedIngredients(Collections.singletonList("盐"));assertEquals("completed",f.confirm(f.adapter.prepareShopping(1L,i,"owned")).status);assertEquals(1,f.items.size());f.items.get(0).setChecked(true);i.setExcludedOwnedIngredients(Collections.singletonList("青菜"));assertThrows(MealConsumptionService.VersionConflict.class,()->f.adapter.prepareShopping(1L,i,"protected"));}
 @Test void lost_response_returns_original_receipt() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.preview(),done=f.confirm(t);f.list.setVersion(8L);ControlledToolTask replay=f.confirm(t);assertEquals(new com.fasterxml.jackson.databind.ObjectMapper().configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true).writeValueAsString(done.steps.get(0).result),new com.fasterxml.jackson.databind.ObjectMapper().configure(com.fasterxml.jackson.databind.SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true).writeValueAsString(replay.steps.get(0).result));assertEquals(2,f.items.size());verify(f.lists,times(1)).batchAdd(eq(1L),any());assertEquals(t.id,f.f.harness.byRequest(1L,t.requestId).id);}
 @Test void cleared_list_new_request_adds_again_without_replaying_old_receipt() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask t=f.preview();f.confirm(t);f.items.clear();f.groups.clear();f.list.setVersion(2L);ControlledToolTask fresh=f.preview();assertEquals("completed",f.confirm(fresh).status);assertEquals(2,f.items.size());assertNotEquals(t.id,fresh.id);verify(f.lists,times(2)).batchAdd(eq(1L),any());}
 @Test void confirmation_auto_prepares_pending_shopping_but_does_not_add() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask calendar=f.workflow(true);ControlledToolTask done=f.confirm(calendar);assertEquals("completed",done.status);TurnView turn=f.f.persistence.store.findTurn(1L,f.f.turnId);assertNotNull(turn.getPendingAction());assertEquals("step-2",turn.getPendingAction().getStepId());assertEquals("shopping_preview",turn.getCards().get(turn.getCards().size()-1).getType());assertTrue(f.items.isEmpty());assertEquals(5L,turn.getWorkspaceRef().getWorkspaceRevision());verifyNoInteractions(f.model);}
 @Test void calendar_done_shopping_failed_resume_only_shopping() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask calendar=f.workflow(true);doThrow(new IllegalStateException("temporarily unavailable")).doCallRealMethod().when(f.lists).getList(1L,"all");assertEquals("completed",f.confirm(calendar).status);assertEquals(1,f.f.persistence.store.continuation(1L,f.f.turnId).getCursor());assertTrue(f.f.persistence.store.findTurn(1L,f.f.turnId).isRetryable());f.turns.resumeWorkflow(1L,f.f.turnId);assertNotNull(f.f.persistence.store.findTurn(1L,f.f.turnId).getPendingAction());verify(f.f.domain.plans,times(1)).insert(any());assertTrue(f.items.isEmpty());verifyNoInteractions(f.model);}
 @Test void failed_alias_link_is_repaired_from_original_calendar_receipt_before_shopping() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ControlledToolTask calendar=f.workflow(true);doThrow(new IllegalStateException("alias storage down")).when(f.aliases).insert(anyLong(),anyString(),anyString());ControlledToolTask saved=f.confirm(calendar);assertEquals("completed",saved.status);assertTrue(saved.retryable);TurnView recovered=f.f.persistence.newStore().findTurn(1L,f.f.turnId);assertTrue(recovered.isRetryable());assertNull(recovered.getPendingAction());assertEquals(1,recovered.getContinuation().getCursor());assertEquals("pending",recovered.getContinuation().getSteps().get(1).getStatus());assertNotNull(recovered.getContinuation().getSteps().get(0).getReceiptRef());assertNotNull(f.f.domain.slots.get("2026-12-31|dinner"));assertTrue(f.items.isEmpty());f.workingAliases();f.turns.resumeWorkflow(1L,f.f.turnId);assertNotNull(f.f.persistence.store.findTurn(1L,f.f.turnId).getPendingAction());verify(f.f.domain.plans,times(1)).insert(any());}
 @Test void plan_unknown_people_does_not_assume_two() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();f.confirm(f.calendar("2026-12-31","dinner"));f.f.domain.slots.get("2026-12-31|dinner").setTargetPeople(null);assertThrows(IllegalArgumentException.class,()->f.adapter.prepareShopping(1L,f.plan("2026-12-31","dinner"),"unknown-people"));}
 @Test void forged_quantity_owner_and_source_reference_are_rejected() throws Exception {AssistantShoppingFixture f=new AssistantShoppingFixture();ShoppingIntent i=f.draft();i.getSourceRef().setDate("2026-12-31");assertThrows(IllegalArgumentException.class,()->f.adapter.prepareShopping(1L,i,"mixed-ref"));Map<String,Object> args=f.f.domain.json.convertValue(f.draft(),Map.class);args.put("quantity",999);WorkflowStep step=new WorkflowStep();step.setKind("shopping_preview");step.setArguments(args);TurnScope scope=new TurnScope();scope.setUserId(1L);assertThrows(IllegalArgumentException.class,()->f.adapter.execute(1L,step,scope));assertThrows(RuntimeException.class,()->f.adapter.prepareShopping(2L,f.draft(),"wrong-owner"));}
}
